// Patterns de références par marque
const REFERENCE_PATTERNS = {
  'hilti': [
    /\b(TE[\s-]?\d+[A-Z]*)/gi,
    /\b(DD[\s-]?\d+[A-Z]*)/gi,
    /\b(SDS[\s-]?\d+)/gi,
    /\b(SF[\s-]?\d+[A-Z]*)/gi
  ],
  'festool': [
    /\b(TS[\s-]?\d+)/gi,
    /\b(OF[\s-]?\d+[A-Z]*)/gi,
    /\b(CT[\s-]?\d+)/gi,
    /\b(RO[\s-]?\d+)/gi
  ],
  'milwaukee': [
    /\b(M\d{2}[A-Z]*\d*)/gi,
    /\b(HD18[A-Z]*)/gi,
    /\b(PD[\s-]?\d+)/gi
  ],
  'makita': [
    /\b(D[A-Z]{2}\d{3,4}[A-Z]*)/gi,
    /\b(BL\d{4})/gi,
    /\b(HR\d{4})/gi
  ],
  'dewalt': [
    /\b(DC[A-Z]\d{3})/gi,
    /\b(DW[A-Z]\d{3})/gi,
    /\b(DCF\d{3})/gi
  ],
  'bosch': [
    /\b(GBH[\s-]?\d+[A-Z]*)/gi,
    /\b(GSR[\s-]?\d+)/gi,
    /\b(GWS[\s-]?\d+)/gi
  ]
};

// Mots-clés importants pour l'outillage (à conserver)
const KEYWORDS_OUTILLAGE = [
  'perceuse', 'visseuse', 'perforateur', 'meuleuse', 'scie', 'ponceuse',
  'raboteuse', 'défonceuse', 'sauteuse', 'circulaire', 'plongeante',
  'burineur', 'marteau', 'piqueur', 'fraiseuse', 'tronçonneuse',
  'aspirateur', 'souffleur', 'cloueuse', 'agrafeuse', 'décapeur',
  'filaire', 'sans fil', 'batterie', 'brushless', 'coffret', 'systainer',
  'v', 'ah', 'w', 'watts', 'volts', 'lithium', 'li-ion',
  'sds', 'plus', 'max', 'compact', 'fuel', 'xr', 'professional'
];

// Mots non pertinents à supprimer
const STOPWORDS = [
  'lot', 'de', 'le', 'la', 'les', 'un', 'une', 'des', 'avec', 'sans',
  'en', 'pour', 'par', 'sur', 'sous', 'et', 'ou', 'très', 'bon', 'état',
  'neuf', 'occasion', 'comme', 'quasi', 'pro', 'professionnel',
  'outil', 'outils', 'machine', 'machines', 'accessoire', 'accessoires'
];

// Extraire référence depuis titre
function extractReference(titre, marque) {
  if (!titre || !marque) return null;

  const marqueLower = marque.toLowerCase();
  const patterns = REFERENCE_PATTERNS[marqueLower];

  if (!patterns) return null;

  for (const pattern of patterns) {
    const matches = titre.match(pattern);
    if (matches && matches.length > 0) {
      // Normaliser la référence (enlever espaces/tirets)
      return matches[0].replace(/[\s-]/g, '').toUpperCase();
    }
  }

  return null;
}

// FALLBACK : Extraire mots-clés intelligents si pas de référence
function extractSmartKeywords(titre, marque) {
  if (!titre) return marque || '';

  // Nettoyer le titre
  let clean = titre.toLowerCase();

  // Enlever la marque du titre (on la rajoutera après)
  if (marque) {
    clean = clean.replace(new RegExp(marque, 'gi'), '');
  }

  // Découper en mots
  const words = clean.split(/[\s\-_,;.()\[\]]+/).filter(w => w.length > 0);

  // Garder les mots pertinents
  const relevantWords = [];

  for (const word of words) {
    // Ignorer les stopwords
    if (STOPWORDS.includes(word)) continue;

    // Garder les nombres (voltage, capacité, etc.)
    if (/^\d+[vwah]*$/.test(word)) {
      relevantWords.push(word);
      continue;
    }

    // Garder les keywords outillage
    if (KEYWORDS_OUTILLAGE.includes(word)) {
      relevantWords.push(word);
      continue;
    }

    // Garder les mots > 4 caractères (probablement importants)
    if (word.length > 4) {
      relevantWords.push(word);
    }
  }

  // Limiter à 4 mots max pour éviter requête trop longue
  const topKeywords = relevantWords.slice(0, 4).join(' ');

  // Retourner marque + mots-clés
  return marque ? `${marque} ${topKeywords}` : topKeywords;
}

// Filtrer et enrichir les produits
const items = $input.all();
const toEstimate = [];

for (const item of items) {
  const data = item.json;

  // Conditions : marque détectée ET pas encore estimé
  if (data.marque_detectee && 
      data.marque_detectee !== '' && 
      (!data.prix_lbc_min || data.prix_lbc_min === '')) {

    // Essayer d'extraire la référence
    const reference = extractReference(data.titre, data.marque_detectee);

    let searchQuery = '';
    let searchType = '';

    if (reference) {
      // CAS 1 : Référence trouvée → Marque + Référence
      searchQuery = `${data.marque_detectee} ${reference}`;
      searchType = 'reference';
    } else {
      // CAS 2 : Pas de référence → Extraction intelligente de mots-clés
      searchQuery = extractSmartKeywords(data.titre, data.marque_detectee);
      searchType = 'keywords';
    }

    toEstimate.push({
      json: {
        lot_id: data.lot_id,
        titre: data.titre,
        marque_detectee: data.marque_detectee,
        reference_extraite: reference || null,
        search_query: searchQuery,
        search_type: searchType,
        prix_interencheres: data.prix || 0,
        url_interencheres: data.url
      }
    });
  }
}

return toEstimate.length > 0 ? toEstimate : [];

// Extraire le titre optimisé de la réponse Ollama
const items = $input.all();
const results = [];

for (const item of items) {
  const ollamaResponse = item.json.response || '';

  // Nettoyer la réponse (enlever guillemets, retours ligne, etc.)
  let titreOptimise = ollamaResponse.trim()
    .replace(/^["'`]+|["'`]+$/g, '')  // Enlever guillemets début/fin
    .replace(/\n.*/g, '')  // Garder seulement la première ligne
    .trim();

  // Récupérer les données originales du node précédent
  const originalData = $('Extraire Référence Produit').all().find(d => 
    d.json.lot_id === item.json.lot_id || true  // Fallback si pas de lot_id
  )?.json || {};

  // Si l'IA n'a pas répondu correctement, utiliser le search_query de base
  if (!titreOptimise || titreOptimise.length < 3 || titreOptimise.length > 100) {
    titreOptimise = originalData.search_query;
  }

  results.push({
    json: {
      lot_id: originalData.lot_id,
      titre: originalData.titre,
      marque_detectee: originalData.marque_detectee,
      reference_extraite: originalData.reference_extraite,
      search_query_auto: originalData.search_query,
      search_query: titreOptimise,
      search_type: originalData.search_type,
      prix_interencheres: originalData.prix_interencheres,
      url_interencheres: originalData.url_interencheres
    }
  });
}

return results;

// Construire URL LeBonCoin pour scraping (offres actives uniquement)
const data = $input.first().json;

// Utiliser la search_query préparée (référence OU mots-clés)
const searchQuery = encodeURIComponent(data.search_query);

// URL SIMPLIFIÉE pour offres ACTIVES
// Format réel LBC: https://www.leboncoin.fr/recherche?text=dewalt
const urlActive = `https://www.leboncoin.fr/recherche?text=${searchQuery}`;

return {
  json: {
    lot_id: data.lot_id,
    titre: data.titre,
    marque_detectee: data.marque_detectee,
    reference_extraite: data.reference_extraite,
    search_query: data.search_query,
    search_type: data.search_type,
    prix_interencheres: data.prix_interencheres,
    url_interencheres: data.url_interencheres,
    lbc_url_active: urlActive
  }
};

// Extraire prix des offres actives uniquement
// Récupérer les données du scraper (HTML)
const scraperData = $input.first().json;
const html = scraperData.html || '';

// Récupérer les données originales du node Construire URL LBC
const originalData = $('Construire URL LBC').first().json;

// Pattern LeBonCoin pour prix
const pricePatterns = [
  /<span[^>]*data-qa-id="aditem_price"[^>]*>([\d\s]+)(?:&nbsp;)?€<\/span>/gi,
  /<p[^>]*data-test-id="price"[^>]*>([\d\s]+)(?:&nbsp;)?€<\/p>/gi,
  /<span[^>]*class="[^"]*price[^"]*"[^>]*>([\d\s]+)(?:&nbsp;)?€<\/span>/gi
];

function extractPrices(html) {
  const prices = [];

  for (const pattern of pricePatterns) {
    let match;
    while ((match = pattern.exec(html)) !== null) {
      const priceStr = match[1].replace(/[\s&nbsp;]/g, '');
      const price = parseInt(priceStr);
      if (price > 0 && price < 50000) {
        prices.push(price);
      }
    }
  }

  return prices;
}

const prices = extractPrices(html);

// Calculer stats
let prix_lbc_min = null;
let prix_lbc_max = null;
let prix_lbc_moyen = null;
let prix_lbc_median = null;
const nb_annonces_actives = prices.length;
const nb_annonces_vendues = 0;
const nb_annonces_total = prices.length;

if (prices.length > 0) {
  const sorted = prices.sort((a, b) => a - b);

  prix_lbc_min = sorted[0];
  prix_lbc_max = sorted[sorted.length - 1];
  prix_lbc_moyen = Math.round(sorted.reduce((sum, p) => sum + p, 0) / sorted.length);

  const mid = Math.floor(sorted.length / 2);
  prix_lbc_median = sorted.length % 2 === 0 
    ? Math.round((sorted[mid - 1] + sorted[mid]) / 2)
    : sorted[mid];
}

// Calculer opportunité et ROI
const prixEstime = prix_lbc_median || prix_lbc_moyen;
const prixAchat = originalData.prix_interencheres || 0;

let opportunite_estimee = null;
let roi_estime = null;

if (prixEstime && prixAchat > 0) {
  opportunite_estimee = prixEstime - prixAchat;
  roi_estime = Math.round(((prixEstime - prixAchat) / prixAchat) * 100);
}

return {
  json: {
    lot_id: originalData.lot_id,
    reference_extraite: originalData.reference_extraite,
    search_query_auto: originalData.search_query_auto || null,
    search_query: originalData.search_query,
    search_type: originalData.search_type,
    prix_lbc_min: prix_lbc_min,
    prix_lbc_max: prix_lbc_max,
    prix_lbc_moyen: prix_lbc_moyen,
    prix_lbc_median: prix_lbc_median,
    nb_annonces_actives: nb_annonces_actives,
    nb_annonces_vendues: nb_annonces_vendues,
    nb_annonces_total: nb_annonces_total,
    opportunite_estimee: opportunite_estimee,
    roi_estime: roi_estime,
    date_estimation: new Date().toISOString()
  }
};
